// IMAGE: a dark background, with a soft glow around everything the [Canvas2D.js] tab draws. The canvas
// layer is a texture, iCanvas2D, that every shader can read.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec3 color = mix(vec3(0.02, 0.02, 0.06), vec3(0.06, 0.04, 0.12), uv.y);
  // A blur of the Canvas2D layer, from samples in rings around this pixel.
  vec3 glow = vec3(0.);
  for (int ring = 1; ring <= 3; ring++) {
    for (int i = 0; i < 8; i++) {
      float angle = 6.2832 * (float(i) + 0.5 * float(ring)) / 8.;
      vec2 offset = vec2(cos(angle), sin(angle)) * float(ring) * 6. / iResolution;
      glow += texture(iCanvas2D, uv + offset).rgb;
    }
  }
  fragColor = vec4(color + 0.35 * glow / 24., 1.);
}

