// CANVAS2D: a bean machine, simulated with the planck.js physics library. Balls fall through rows
// of pegs, bouncing left or right at each, and pile up in a bell curve.
import planck from "planck";

const WIDTH = 9, HEIGHT = 16;  // The board, in metres; the view below fits it to the canvas.
const BINS = 15;
const BIN_HEIGHT = 5.5;
const BALL_RADIUS = 0.12, PEG_RADIUS = 0.1;
const MAX_BALLS = 220;
const FUNNEL_TOP = 14.4, FUNNEL_GAP = 0.4;

// Runs once after each build: puts the pegs, walls and bins in a new world. What it returns is
// `data` in draw.
function setup() {
  const world = new planck.World({gravity: planck.Vec2(0, -10)});
  const ground = world.createBody();
  const wall = (x1, y1, x2, y2) => ground.createFixture(planck.Edge(planck.Vec2(x1, y1), planck.Vec2(x2, y2)));
  wall(0, 0, WIDTH, 0);
  wall(0, 0, 0, HEIGHT);
  wall(WIDTH, 0, WIDTH, HEIGHT);
  // A funnel drops the balls in the middle.
  wall(0.5, FUNNEL_TOP, WIDTH / 2 - FUNNEL_GAP, 13.2);
  wall(WIDTH - 0.5, FUNNEL_TOP, WIDTH / 2 + FUNNEL_GAP, 13.2);
  const binWidth = WIDTH / BINS;
  for (let i = 1; i < BINS; i++) {
    wall(i * binWidth, 0, i * binWidth, BIN_HEIGHT);
  }
  const pegs = [];
  // Rows of pegs, each row offset by half a bin from the one above.
  for (let row = 0; row < 10; row++) {
    const y = 12.6 - row * 0.7;
    for (let x = (row % 2 ? binWidth : binWidth / 2); x < WIDTH; x += binWidth) {
      ground.createFixture(planck.Circle(planck.Vec2(x, y), PEG_RADIUS));
      pegs.push([x, y]);
    }
  }
  return {world, pegs, balls: [], binWidth};
}

function dropBall({world, balls}) {
  const ball = world.createDynamicBody({
    position: planck.Vec2(WIDTH / 2 + (Math.random() - 0.5) * 0.6, 15.5),
    linearDamping: 1,  // Like air resistance, so balls don't fly off the pegs.
  });
  ball.createFixture(planck.Circle(BALL_RADIUS), {density: 1, friction: 0.1, restitution: 0.3});
  balls.push(ball);
}

// Runs once a step, 60 times a second, so the simulation moves on 1/60 s each time.
function draw(ctx, {frame, width, data}) {
  if (frame % 5 === 0 && data.balls.length < MAX_BALLS) {
    dropBall(data);
  }
  data.world.step(1 / 60);

  clear(ctx);
  const hue = i => `hsl(${200 + 140 * i / MAX_BALLS}, 90%, 65%)`;
  drawList(ctx, [
    Set({strokeStyle: "#ffffff80"}),
    AbsoluteLineWidth(3),
    Line({pts: [[0.5, FUNNEL_TOP], [WIDTH / 2 - FUNNEL_GAP, 13.2]]}),
    Line({pts: [[WIDTH - 0.5, FUNNEL_TOP], [WIDTH / 2 + FUNNEL_GAP, 13.2]]}),
    Array.from({length: BINS - 1}, (_, i) => Line({pts: [[(i + 1) * data.binWidth, 0], [(i + 1) * data.binWidth, BIN_HEIGHT]]})),
    Set({fillStyle: "#ffffffc0"}),
    data.pegs.map(center => Disk({center, radius: PEG_RADIUS})),
    data.balls.map((ball, i) => [
      Set({fillStyle: hue(i)}),
      Disk({center: [ball.getPosition().x, ball.getPosition().y], radius: BALL_RADIUS}),
    ]),
  ], {xmin: 0, xmax: WIDTH, ymin: 0, ymax: HEIGHT});

  ctx.font = "600 40px Inter";
  ctx.textAlign = "center";
  ctx.fillStyle = "white";
  ctx.fillText(data.balls.length + " balls", width / 2, 64);
}
